:root{
  --b:#0ea5e9;--b2:#38bdf8;--b3:#0284c7;--bd-b:#082f49;
  --bg:#04090f;--bg2:#060d17;--bg3:#091525;
  --bd:#0f2240;--tx:#e8f4fd;--tx2:#5c8aac;
  --g:#10b981;
  --font:'Syne',sans-serif;--body:'Outfit',sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{font-family:var(--body);background:var(--bg);color:var(--tx);overflow-x:hidden}
::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:var(--b)}

/* AMBIENT GLOW */
body::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:0;
  background:
    radial-gradient(ellipse 60% 50% at 80% 20%,rgba(14,165,233,.07) 0%,transparent 60%),
    radial-gradient(ellipse 40% 60% at 10% 80%,rgba(14,165,233,.04) 0%,transparent 50%)}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:100;height:72px;
  display:flex;align-items:center;justify-content:space-between;padding:0 48px;
  background:rgba(4,9,15,.9);backdrop-filter:blur(20px);border-bottom:1px solid var(--bd)}
.logo{display:flex;align-items:center;gap:12px;text-decoration:none}
.logo-mark{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,var(--b),var(--b3));
  display:flex;align-items:center;justify-content:center;font-size:18px}
.logo-name{font-family:var(--font);font-size:20px;font-weight:800;color:var(--tx);letter-spacing:-.5px}
.logo-sub{font-size:10px;color:var(--tx2);letter-spacing:2px;text-transform:uppercase;margin-left:2px}
.nav-links{display:flex;gap:32px;align-items:center}
.nav-links a{font-size:13px;color:var(--tx2);text-decoration:none;transition:color .3s;letter-spacing:.5px}
.nav-links a:hover{color:var(--b)}
.nav-pill{padding:10px 24px;background:rgba(14,165,233,.1);border:1px solid rgba(14,165,233,.3);color:var(--b2);
  border-radius:100px;font-size:12px;font-weight:600;text-decoration:none;transition:all .3s;letter-spacing:.5px}
.nav-pill:hover{background:rgba(14,165,233,.2);border-color:var(--b);transform:translateY(-1px)}

/* HERO */
.hero{min-height:100vh;display:flex;align-items:center;padding:120px 48px 80px;position:relative;overflow:hidden}

/* Animated grid */
.hero-grid{position:absolute;inset:0;z-index:0;overflow:hidden;opacity:.04}
.hero-grid::before{content:'';position:absolute;inset:-50%;
  background-image:
    linear-gradient(rgba(14,165,233,1) 1px,transparent 1px),
    linear-gradient(90deg,rgba(14,165,233,1) 1px,transparent 1px);
  background-size:60px 60px;
  animation:gridPan 20s linear infinite}

.hero-content{position:relative;z-index:2;max-width:680px}
.hero-status{display:inline-flex;align-items:center;gap:8px;padding:6px 16px;
  background:rgba(16,185,129,.08);border:1px solid rgba(16,185,129,.25);border-radius:100px;
  font-size:11px;color:var(--g);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:28px;
  animation:fadeUp .6s ease both}
.hero-status::before{content:'';width:6px;height:6px;border-radius:50%;background:var(--g);animation:blink 2s infinite}

h1.htitle{font-family:var(--font);font-size:clamp(48px,7vw,96px);font-weight:800;line-height:.95;
  letter-spacing:-2px;margin-bottom:24px;animation:fadeUp .6s ease both .15s}
h1.htitle .blue{color:var(--b2)}
h1.htitle .outline{-webkit-text-stroke:1px rgba(14,165,233,.4);color:transparent}

.hero-desc{font-size:16px;color:var(--tx2);line-height:1.8;max-width:500px;margin-bottom:40px;font-weight:300;
  animation:fadeUp .6s ease both .25s}

.hero-btns{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:64px;animation:fadeUp .6s ease both .35s}
.btn-blue{display:inline-flex;align-items:center;gap:10px;padding:16px 36px;
  background:linear-gradient(135deg,var(--b),var(--b3));color:#fff;border-radius:10px;
  font-size:14px;font-weight:600;text-decoration:none;transition:all .3s;letter-spacing:.3px}
.btn-blue:hover{transform:translateY(-2px);box-shadow:0 8px 32px rgba(14,165,233,.3)}
.btn-out{display:inline-flex;align-items:center;gap:10px;padding:15px 32px;
  background:transparent;color:var(--tx);border:1px solid var(--bd);border-radius:10px;
  font-size:14px;text-decoration:none;transition:all .3s}
.btn-out:hover{border-color:var(--b);color:var(--b)}

.hero-kpis{display:flex;gap:0;animation:fadeUp .6s ease both .45s}
.kpi{padding:24px 36px;border-right:1px solid var(--bd);first-child{border-left:1px solid var(--bd)}}
.kpi:first-child{padding-left:0}
.kpi:last-child{border-right:none}
.kpi .kn{font-family:var(--font);font-size:36px;font-weight:800;color:var(--b2);letter-spacing:-1px;line-height:1}
.kpi .kl{font-size:11px;color:var(--tx2);letter-spacing:1.5px;text-transform:uppercase;margin-top:6px}

/* Hero visual */
.hero-visual{position:absolute;right:0;top:50%;transform:translateY(-50%);width:42%;z-index:1;
  opacity:.9;animation:fadeIn .8s ease both .3s}
.hero-visual-bg{width:100%;aspect-ratio:1;display:flex;align-items:center;justify-content:center;position:relative}
/* Concentric rings */
.ring{position:absolute;border-radius:50%;border:1px solid rgba(14,165,233,.08)}
.ring-1{width:400px;height:400px;animation:rotateRing 20s linear infinite}
.ring-2{width:300px;height:300px;border-color:rgba(14,165,233,.12);animation:rotateRing 14s linear infinite reverse}
.ring-3{width:200px;height:200px;border-color:rgba(14,165,233,.18);animation:rotateRing 8s linear infinite}
.ring-dot{position:absolute;width:8px;height:8px;border-radius:50%;background:var(--b);top:-4px;left:50%;transform:translateX(-50%)}
.hero-car{font-size:120px;opacity:.1;position:relative;z-index:2;animation:float 3s ease-in-out infinite}
.hero-card-badge{position:absolute;bottom:40px;right:40px;padding:20px 24px;
  background:var(--bg2);border:1px solid var(--bd);border-radius:12px;
  backdrop-filter:blur(10px);min-width:200px;animation:fadeUp .8s ease both .6s}
.hcb-label{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--tx2);margin-bottom:6px}
.hcb-value{font-family:var(--font);font-size:22px;font-weight:800;color:var(--b2);margin-bottom:4px}
.hcb-sub{font-size:11px;color:var(--g);display:flex;align-items:center;gap:4px}

/* SERVICES */
.section{padding:100px 48px;position:relative;z-index:1}
.sec-eyebrow{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--b);margin-bottom:10px;display:flex;align-items:center;gap:8px}
.sec-eyebrow::before{content:'';width:24px;height:1px;background:var(--b)}
.sec-title{font-family:var(--font);font-size:clamp(36px,4.5vw,56px);font-weight:800;letter-spacing:-1px;line-height:1;margin-bottom:48px}
.sec-title .dim{color:var(--tx2);font-weight:400}

.srv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.srv-card{background:var(--bg2);border:1px solid var(--bd);border-radius:16px;padding:36px;
  position:relative;overflow:hidden;transition:all .4s;cursor:default}
.srv-card::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(14,165,233,.04),transparent);opacity:0;transition:opacity .4s}
.srv-card:hover{border-color:rgba(14,165,233,.25);transform:translateY(-4px);box-shadow:0 12px 40px rgba(0,0,0,.3)}
.srv-card:hover::before{opacity:1}
.srv-card .corner{position:absolute;top:0;right:0;width:0;height:0;
  border-style:solid;border-width:0 40px 40px 0;border-color:transparent rgba(14,165,233,.15) transparent transparent;
  transition:border-width .4s}
.srv-card:hover .corner{border-width:0 60px 60px 0}
.srv-ico{width:52px;height:52px;border-radius:12px;background:rgba(14,165,233,.08);
  border:1px solid rgba(14,165,233,.15);display:flex;align-items:center;justify-content:center;font-size:22px;margin-bottom:20px}
.srv-name{font-family:var(--font);font-size:20px;font-weight:700;margin-bottom:8px;letter-spacing:-.3px}
.srv-desc{font-size:13px;color:var(--tx2);line-height:1.7}

/* WHY */
.why{background:var(--bg2);border-top:1px solid var(--bd);border-bottom:1px solid var(--bd);padding:100px 48px}
.why-inner{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.why-left{}
.why-pill{display:inline-flex;align-items:center;gap:8px;padding:6px 16px;background:rgba(14,165,233,.08);border:1px solid rgba(14,165,233,.2);border-radius:100px;font-size:11px;color:var(--b2);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:24px}
.why-headline{font-family:var(--font);font-size:clamp(36px,4.5vw,52px);font-weight:800;letter-spacing:-1px;line-height:1.1;margin-bottom:20px}
.why-headline span{color:var(--b2)}
.why-body{font-size:14px;color:var(--tx2);line-height:1.9;margin-bottom:32px;font-weight:300}
.why-right{display:flex;flex-direction:column;gap:16px}
.why-item{padding:24px;background:var(--bg3);border:1px solid var(--bd);border-radius:12px;
  display:flex;align-items:flex-start;gap:16px;transition:all .4s}
.why-item:hover{border-color:rgba(14,165,233,.2);transform:translateX(6px)}
.why-item-ico{width:40px;height:40px;border-radius:10px;background:rgba(14,165,233,.08);
  display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0}
.why-item-title{font-family:var(--font);font-size:15px;font-weight:700;margin-bottom:4px;letter-spacing:-.2px}
.why-item-desc{font-size:12px;color:var(--tx2);line-height:1.6}

/* TESTIMONIALS */
.tests{padding:100px 48px}
.tests-inner{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:48px}
.test{background:var(--bg2);border:1px solid var(--bd);border-radius:16px;padding:32px;transition:all .4s}
.test:hover{border-color:rgba(14,165,233,.2);transform:translateY(-3px)}
.test-head{display:flex;align-items:center;gap:12px;margin-bottom:20px}
.test-avatar{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,rgba(14,165,233,.2),rgba(14,165,233,.05));
  display:flex;align-items:center;justify-content:center;font-size:20px;border:1px solid rgba(14,165,233,.15)}
.test-author-name{font-family:var(--font);font-size:14px;font-weight:700;letter-spacing:-.2px}
.test-stars{color:var(--b);font-size:11px;margin-top:2px}
.test-text{font-size:13px;color:var(--tx2);line-height:1.8;font-style:italic}

/* CONTACT */
.contact{padding:100px 48px;background:var(--bg2);border-top:1px solid var(--bd)}
.contact-inner{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:start}
.contact-title{font-family:var(--font);font-size:clamp(36px,4.5vw,60px);font-weight:800;letter-spacing:-1.5px;line-height:1;margin-bottom:20px}
.contact-title span{color:var(--b2)}
.contact-desc{font-size:14px;color:var(--tx2);line-height:1.9;margin-bottom:32px}
.contact-item{display:flex;align-items:center;gap:16px;padding:18px 20px;
  background:var(--bg3);border:1px solid var(--bd);border-radius:12px;margin-bottom:10px;
  text-decoration:none;color:var(--tx);transition:all .3s}
.contact-item:hover{border-color:rgba(14,165,233,.3);transform:translateX(6px)}
.ci-ico{width:38px;height:38px;border-radius:10px;background:rgba(14,165,233,.08);
  display:flex;align-items:center;justify-content:center;color:var(--b);font-size:14px;flex-shrink:0}
.ci-label{font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx2);margin-bottom:2px}
.ci-value{font-size:14px}
.contact-visual{background:var(--bg3);border:1px solid var(--bd);border-radius:16px;
  aspect-ratio:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;
  font-size:80px;opacity:.08;position:relative;overflow:hidden}
.contact-visual::after{content:'Panamericana Norte 5001, Conchalí';position:absolute;bottom:32px;left:50%;transform:translateX(-50%);
  font-size:12px;color:var(--tx2);opacity:1;white-space:nowrap;font-size:12px}

/* FOOTER */
footer{background:var(--bg);border-top:1px solid var(--bd);padding:60px 48px}
.ft-top{display:grid;grid-template-columns:2fr 1fr 1fr;gap:48px;margin-bottom:48px}
.ft-logo{font-family:var(--font);font-size:22px;font-weight:800;letter-spacing:-.5px;margin-bottom:12px;color:var(--tx)}
.ft-logo span{color:var(--b2)}
.ft-desc{font-size:13px;color:var(--tx2);line-height:1.7;margin-bottom:16px}
.ft-title{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--b);margin-bottom:16px}
.ft-link{display:block;font-size:13px;color:var(--tx2);text-decoration:none;margin-bottom:8px;transition:color .3s}
.ft-link:hover{color:var(--b2)}
.ft-bot{border-top:1px solid var(--bd);padding-top:24px;display:flex;justify-content:space-between;font-size:12px;color:var(--tx2);letter-spacing:.3px}
.ft-bot span{color:var(--b2)}

/* WA */
.wa{position:fixed;bottom:28px;right:28px;z-index:200;width:56px;height:56px;border-radius:16px;
  background:#25D366;display:flex;align-items:center;justify-content:center;
  font-size:24px;color:#fff;text-decoration:none;
  box-shadow:0 4px 24px rgba(37,211,102,.3);transition:all .3s}
.wa:hover{transform:scale(1.1);border-radius:50%}

/* ANIMATIONS */
@keyframes fadeUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
@keyframes gridPan{from{transform:translate(0,0)}to{transform:translate(60px,60px)}}
@keyframes rotateRing{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
.reveal{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease}
.reveal.vis{opacity:1;transform:translateY(0)}
.d1{transition-delay:.1s}.d2{transition-delay:.2s}.d3{transition-delay:.3s}

@media(max-width:900px){
  .nav{padding:0 20px}
  .hero{padding:100px 20px 60px;flex-direction:column}
  .hero-visual{display:none}
  .section,.tests,.contact{padding:60px 20px}
  .why{padding:60px 20px}
  .srv-grid,.tests-inner,.why-inner,.contact-inner,.ft-top{grid-template-columns:1fr}
  .kpi{padding:16px 20px}
  footer{padding:40px 20px}
  .ft-bot{flex-direction:column;gap:8px}
}
